// ---------- progression helpers ----------
const RAR_MUL={1:0.75,2:0.85,3:1,4:1.22,5:1.6};
function charMaxLv(st){ return Math.min(100,25+15*st.star); }
function charExpNeed(lv){ return Math.floor(40*Math.pow(lv,1.35)); }
function charStats(id,st){
  st=st||S.chars[id]||newChar(id); const c=CHAR[id], k=CLASSES[c.cls];
  const affLv=Math.floor(st.aff/100);
  const mul=RAR_MUL[c.rar]*lvMul(st.lvl)*(1+0.16*(st.star-c.rar))*(st.evo?1.3:1)*(1+0.02*affLv);
  return { atk:Math.round(100*k.dmg*mul), range:Math.round(k.range*(st.evo?1.08:1)), cd:k.cd, aspd:+(1/k.cd).toFixed(2),
    crit:(k.crit||0.05)+(c.elem==='wind'?0.03:0), hp:Math.round(800*mul), cost:deployCost(c,st), skillLv:st.skill };
}
function charPower(id){ const s=charStats(id); return Math.round(s.atk*s.aspd*4+s.range*2+s.hp*0.3+s.skillLv*80); }
function totalPower(){ return teamIds().reduce((a,id)=>a+charPower(id),0); }
function teamIds(){ return (S.team[S.preset]||[]).filter(id=>S.chars[id]); }
function playerExpNeed(lv){ return Math.floor(120*Math.pow(lv,1.45)); }
function staminaMax(){ return 58+S.lvl*2; }
function tickStamina(){ const per=180000; const mx=staminaMax(); if(S.stamina>=mx){ S.staminaT=Date.now(); return; } const n=Math.floor((Date.now()-S.staminaT)/per); if(n>0){ S.stamina=Math.min(mx,S.stamina+n); S.staminaT+=n*per; } }
function addPlayerExp(x){ S.exp+=x; let up=false; while(S.exp>=playerExpNeed(S.lvl)){ S.exp-=playerExpNeed(S.lvl); S.lvl++; up=true; S.stamina=Math.max(S.stamina,staminaMax()); } return up; }
function totalStars(){ let n=0; for(const k in S.stages) n+=S.stages[k].stars||0; return n; }
function ownedCount(){ return Object.keys(S.chars).length; }
function statVal(k){
  if(k==='own') return ownedCount(); if(k==='stars') return totalStars(); if(k==='plv') return S.lvl;
  if(k==='star5') return Object.values(S.chars).some(c=>c.star>=5)?1:0;
  if(k==='teamsize') return teamIds().length; if(k==='maxlv') return Math.max(...Object.values(S.chars).map(c=>c.lvl));
  return S.stats[k]||0;
}
function track(k,n=1){
  S.stats[k]=(S.stats[k]||0)+n; resetPeriods();
  S.daily.p[k]=(S.daily.p[k]||0)+n; S.weekly.p[k]=(S.weekly.p[k]||0)+n; save();
}
function resetPeriods(){
  if(S.daily.date!==today()){ S.daily={date:today(),p:{login:1},claimed:{}}; }
  if(S.weekly.wk!==weekKey()){ S.weekly={wk:weekKey(),p:{},claimed:{}}; }
}
function grant(r,mult=1){
  const out=[];
  for(const k in r){ const v=Math.round(r[k]*mult); if(!v) continue;
    if(k==='gold'){ S.gold+=v; S.stats.goldEarn+=v; S.daily.p.goldEarn=(S.daily.p.goldEarn||0)+v; S.weekly.p.goldEarn=(S.weekly.p.goldEarn||0)+v; }
    else if(k==='gems') S.gems+=v; else if(k==='stamina') S.stamina+=v; else if(k==='exp') addPlayerExp(v);
    else if(k.startsWith('medal_')){ const id=k.slice(6); if(S.chars[id]) S.chars[id].medal+=v; }
    else if(k.startsWith('char_')){ addChar(k.slice(5)); }
    else if(k.startsWith('cur_')){ S.eventCur[k.slice(4)]=(S.eventCur[k.slice(4)]||0)+v; }
    else if(ITEMS[k]) S.items[k]=(S.items[k]||0)+v;
    else S.mat[k]=(S.mat[k]||0)+v;
    out.push([k,v]);
  }
  save(); return out;
}
function addChar(id){ if(S.chars[id]){ S.chars[id].medal+=MEDAL_DUP[CHAR[id].rar]; return false; } S.chars[id]=newChar(id); return true; }
