const SCOPE_T={r:'ในระยะ',a:'ทั้งแผนที่',t:'กลุ่มศัตรูแถวหน้า'};
const BUFF_T={atk:'ATK',spd:'ความเร็วโจมตี',crit:'คริติคอล',rng:'ระยะโจมตี'};
const WHO_T={self:'ตัวเอง',all:'ป้อมทุกตัว',near:'ป้อมรอบตัว'};
function fxText(f){ const [k,a,b,c,d]=f; switch(k){
 case 'area': return `ดาเมจ x${a} รอบตัว`; case 'all': return `ดาเมจ x${a} ศัตรูทั้งแผนที่`; case 'top': return `ดาเมจ x${a===1?b:b} ใส่ศัตรูแข็งแรงสุด ${a} ตัว`;
 case 'first': return `ยิง x${b} ใส่ศัตรูแถวหน้า ${a} ตัว`; case 'meteor': return `ดาวตกดาเมจ x${a} วงกว้าง`; case 'rain': return `ฝนโจมตีพื้นที่ ${b} วิ`;
 case 'chain': return `สายฟ้าโซ่ ${a} เป้า ดาเมจ x${b}`; case 'freeze': return `แช่แข็ง ${a} วิ (${SCOPE_T[b]})`; case 'stun': return `สตัน ${a} วิ (${SCOPE_T[b]})`;
 case 'slow': return `ช้าลง ${Math.round(a*100)}% ${b} วิ (${SCOPE_T[c]})`; case 'root': return `รัดตรึง ${a} วิ (${SCOPE_T[b]})`; case 'burn': return `เผาไหม้ ${b} วิ (${SCOPE_T[c]})`;
 case 'poison': return `ติดพิษ ${b} วิ (${SCOPE_T[c]})`; case 'curse': return `คำสาป รับดาเมจ+20% ${a} วิ (${SCOPE_T[b]})`; case 'push': return `ผลักศัตรูถอยหลัง (${SCOPE_T[b]})`;
 case 'abreak': return `ทำลายเกราะ ${a} วิ (${SCOPE_T[b]})`; case 'exec': return `ประหารศัตรู HP ต่ำกว่า ${Math.round(a*100)}% (ไม่รวมบอส)`;
 case 'buff': return a==='crit'&&b>=1?`${WHO_T[d]} คริ 100% ${c} วิ`:a==='crit'?`${WHO_T[d]} คริ +${Math.round(b*100)}% ${c} วิ`:`${WHO_T[d]} ${BUFF_T[a]} x${b} ${c} วิ`;
 case 'cleanse': return `ล้างสถานะ + กันสถานะ ${a} วิ`; case 'heal': return `ฐาน +${a} HP`; case 'energy': return `Energy +${a}`; case 'gauge': return `ชาร์จสกิลเพื่อน +${a}%`;
 case 'lucky': return 'สุ่ม 1 อย่าง: ระเบิดทั้งแผนที่ / แช่แข็งทั้งหมด / Energy +200'; } return ''; }
const SK_FX_IC={area:'boom',all:'nuke2',top:'skullTarget',first:'target',meteor:'meteor',rain:'rainSword',chain:'storm',freeze:'snow',stun:'bolt',slow:'hourglass',root:'thorns',burn:'fire',poison:'poison',curse:'skull',push:'water',abreak:'spikeShield',exec:'swordSlash',buff:'swordUp',cleanse:'holyShield',heal:'heartPlus',energy:'potionBlue',gauge:'clock',lucky:'chest'};
for(const id in CS){ const [n,fx]=CS[id]; if(CHAR[id]) CHAR[id].sk={n,fx,d:fx.map(fxText).join(' • '),ic:SK_FX_IC[fx[0][0]]}; }
function skillOf(c){ return c.sk||SKILLS[CLASSES[c.cls].skill]; }
// sanity: every character unique
(function(){ const seen={}; for(const c of CHARS){ const s=c.sk?JSON.stringify(c.sk.fx):'none:'+c.id; if(seen[s]) console.warn('DUP SKILL',c.id,seen[s]); seen[s]=c.id; if(!c.sk) console.warn('NO SKILL',c.id); } })();

function castUnique(t,pw){
  const sk=t.c.sk, ts=towerStats(t), col=ELEMENTS[t.c.elem].c, el=t.c.elem, atk=ts.atk*pw*SK_RAR[t.c.rar];
  const durM=SK_RAR_D[t.c.rar];
  const live=()=>B.enemies.filter(e=>!e.dead);
  const front=live().sort((a,b)=>b.d-a.d)[0];
  const scope=s=> s==='a'?live() : s==='t'?(front?live().filter(e=>Math.hypot(e.x-front.x,e.y-front.y)<170):[]) : live().filter(e=>Math.hypot(e.x-t.x,e.y-t.y)<ts.range*1.3);
  const ring=(x,y,r,c)=>B.fx.push({type:'ring',x,y,t:0,max:0.8,c:c||col,r,thick:10});
  const pimg=PROJ_IMG[projOf(t.c)];
  for(const f of sk.fx){ const [k,a,b,c,d]=f;
    switch(k){
      case 'area': { const r=ts.range*b; ring(t.x,t.y,r); for(const e of live()) if(Math.hypot(e.x-t.x,e.y-t.y)<r){ damage(e,atk*a,{elem:el,src:t}); burst(e.x,e.y-30,6,[col,'#fff'],'star',180);} break; }
      case 'all': B.flash=0.4; for(const e of live()){ damage(e,atk*a,{elem:el,src:t}); burst(e.x,e.y-30,6,[col,'#fff'],'star',200);} break;
      case 'top': for(const e of live().sort((x,y)=>y.hp-x.hp).slice(0,a)){ damage(e,atk*b,{elem:el,src:t,crit:a===1}); B.fx.push({type:'bolt',x1:t.x,y1:t.y-60,x2:e.x,y2:e.y-30,t:0,max:0.35,c:col,w:5}); } break;
      case 'first': live().sort((x,y)=>y.d-x.d).slice(0,a).forEach((e,i)=>B.proj.push({type:projOf(t.c),x:t.x,y:t.y-60,sx:t.x,sy:t.y-60,tgt:e,tx:e.x,ty:e.y,spd:900,t:0,src:t,dmg:atk*b,crit:false,elem:el,splash:0,arc:false,rot:0,trail:[]})); break;
      case 'meteor': { let tg=null; for(const e of live()) if(!tg||e.hp>tg.hp) tg=e; if(tg) B.fx.push({type:'meteor',x:tg.x,y:tg.y,t:0,max:0.8,tgt:tg,dmg:atk*a,src:t,c:col,r:b}); break; }
      case 'rain': { const tg=front; if(tg) B.fx.push({type:'rain',x:tg.x,y:tg.y,t:0,max:b,r:140,dmg:atk*a,src:t,tick:0}); break; }
      case 'chain': { let cur=live().sort((x,y)=>y.d-x.d)[0], prev={x:t.x,y:t.y-60}; const hit=new Set();
        for(let i=0;i<a&&cur;i++){ hit.add(cur); B.fx.push({type:'bolt',x1:prev.x,y1:prev.y,x2:cur.x,y2:cur.y-25,t:0,max:0.4,c:col,w:5}); damage(cur,atk*b,{elem:el,src:t}); prev={x:cur.x,y:cur.y-25};
          let nx=null,nd=260; for(const o of live()){ if(hit.has(o)) continue; const dd=Math.hypot(o.x-cur.x,o.y-cur.y); if(dd<nd){nd=dd;nx=o;} } cur=nx; } break; }
      case 'freeze': for(const e of scope(b)){ e.st.freeze=Math.max(e.st.freeze||0,(e.boss?a*0.4:a)*durM); burst(e.x,e.y-30,6,['#dff9ff','#9fe8ff'],'shard',160);} AudioSys.sfx('freeze'); break;
      case 'stun': for(const e of scope(b)){ e.st.stun=Math.max(e.st.stun||0,(e.boss?a*0.4:a)*durM); burst(e.x,e.y-40,5,['#ffe25a','#fff'],'star',140);} break;
      case 'slow': for(const e of scope(c)) e.st.slow={v:e.boss?a*0.6:a,t:b}; break;
      case 'root': for(const e of scope(b)){ e.st.root=Math.max(e.st.root||0,(e.boss?a*0.4:a)*durM); burst(e.x,e.y-10,6,['#5fd068','#bfffb0'],'leaf',140);} break;
      case 'burn': for(const e of scope(c)) if(e.st.burn.length<4) e.st.burn.push({dps:atk*a,t:b}); break;
      case 'poison': for(const e of scope(c)) if(e.st.poison.length<4) e.st.poison.push({dps:atk*a,t:b}); break;
      case 'curse': for(const e of scope(b)){ e.st.curse=Math.max(e.st.curse||0,a); burst(e.x,e.y-40,5,['#a571ff','#fff'],'star',140);} break;
      case 'push': for(const e of scope(b)){ if(!e.boss) e.d=Math.max(0,e.d-a); else e.d=Math.max(0,e.d-a*0.25); burst(e.x,e.y-10,6,['#9fdcff','#fff'],'circle',160);} break;
      case 'abreak': for(const e of scope(b)){ e.st.abreak=Math.max(e.st.abreak||0,a); e.shield=0; } break;
      case 'exec': for(const e of live()) if(!e.boss&&Math.hypot(e.x-t.x,e.y-t.y)<ts.range*1.3&&e.hp<e.maxHp*a){ damage(e,e.hp+1,{src:t,pierce:true}); floatText(e.x,e.y-60,'ประหาร!','#ff5f7a',18,false,'skull'); } break;
      case 'buff': { const who=d==='self'?[t]:d==='all'?B.towers:B.towers.filter(o=>Math.hypot(o.x-t.x,o.y-t.y)<ts.range*1.2);
        for(const o of who){ o.ub=o.ub||{}; o.ub[a]={v:b,t:c}; burst(o.x,o.y-60,8,['#ffe36b','#ff9ad5'],'star',150);} break; }
      case 'cleanse': for(const o of B.towers){ o.db={}; o.immune=Math.max(o.immune,a); burst(o.x,o.y-50,8,['#fff6a8','#ffd1f2'],'plus',140);} AudioSys.sfx('heal'); break;
      case 'heal': B.baseHp=Math.min(B.baseMax,B.baseHp+a); floatText(768,180,'ฐาน +'+a,'#ff7ab8',26,true,'heartPlus'); break;
      case 'energy': B.energy+=a; floatText(t.x,t.y-150,'+'+a+' Energy','#ffe36b',22,true,'potionBlue'); break;
      case 'gauge': for(const o of B.towers) if(o!==t) o.gauge=Math.min(skillNeed(o),o.gauge+skillNeed(o)*a/100); break;
      case 'lucky': { const r=Math.floor(Math.random()*3); if(r===0){ for(const e of live()) damage(e,atk*3,{elem:el,src:t}); B.shake=0.5; floatText(768,240,'ระเบิด!','#ff9a3a',30,true,'nuke2'); }
        else if(r===1){ for(const e of live()) e.st.freeze=e.boss?1:2.5; floatText(768,240,'แช่แข็ง!','#9fe8ff',30,true,'snow'); } else { B.energy+=200; floatText(768,240,'+200 Energy','#ffe36b',30,true,'potionBlue'); } break; }
    }
  }
  if(pimg&&IMG[pimg]) for(let i=0;i<8;i++){ const a=i*Math.PI/4; B.parts.push({x:t.x,y:t.y-60,vx:Math.cos(a)*260,vy:Math.sin(a)*260-80,life:0.7,max:0.7,s:7,c:col,type:'star',rot:0,vr:6,g:200}); }
  ring(t.x,t.y,120,'#fff6a8');
}

function isAoe(c){ const sk=c.sk; return !!sk&&sk.fx.some(f=>['area','all','meteor','rain','chain'].includes(f[0])||(f[0]==='first'&&f[1]>=5)||(f[0]==='top'&&f[1]>=4)); }
CLASSES.icemage.splash=60; CLASSES.druid.splash=55; CLASSES.gunner.splash=40;
MINI_LIMIT.rush=3;
const SK_RAR={1:0.8,2:0.85,3:1,4:1.3,5:1.95}, SK_RAR_D={1:0.9,2:0.9,3:1,4:1.1,5:1.3}, SK_RAR_CD={1:1.05,2:1.05,3:1,4:0.92,5:0.8};
// ---------- skill cooldowns: stronger skill = longer delay ----------
const SC_SCOPE={a:2.2,t:1.2,r:1};
function skillScore(fx){ let s=0; for(const [k,a,b,c,d] of fx){ switch(k){
  case 'area': s+=a*1.1*b; break; case 'all': s+=a*2.6; break; case 'top': s+=a*b*0.32; break; case 'first': s+=a*b*0.22; break;
  case 'meteor': s+=a*0.9; break; case 'rain': s+=a*b*0.9; break; case 'chain': s+=a*b*0.28; break;
  case 'freeze': case 'stun': s+=a*1.1*SC_SCOPE[b]; break; case 'root': s+=a*0.9*SC_SCOPE[b]; break;
  case 'slow': s+=a*b*0.45*SC_SCOPE[c]; break; case 'burn': case 'poison': s+=a*b*0.7*SC_SCOPE[c]; break;
  case 'curse': case 'abreak': s+=a*0.18*SC_SCOPE[b]; break; case 'push': s+=a/70*SC_SCOPE[b]; break; case 'exec': s+=3; break;
  case 'buff': s+=(a==='crit'?(b>=1?0.6:b):(b-1))*c*({all:1.6,near:1,self:0.5}[d]||1); break;
  case 'cleanse': s+=a*0.35; break; case 'heal': s+=a*0.9; break; case 'energy': s+=a/45; break; case 'gauge': s+=a/14; break; case 'lucky': s+=4.5; break; } } return s; }
function applySkillCd(){ for(const c of CHARS) if(c.sk){ c.sk.score=skillScore(c.sk.fx); c.sk.cd=Math.round(clamp((6+c.sk.score*2.3)*SK_RAR_CD[c.rar],8,40)); c.sk.d=c.sk.fx.map(fxText).join(' • ')+(c.rar>=5?' • ✦ การ์ดทอง: พลังสกิล x1.7 ควบคุมนานขึ้น 30%':c.rar===4?' • พลังสกิล x1.25':''); } }
applySkillCd();
const COMBO_CD=55;
function skillRate(t){ return 100/((t.c.sk&&t.c.sk.cd)||15)*(1+0.04*(t.st.skill-1))*(1+B.bonus.charge); }
function skillLeft(t){ return Math.max(0,Math.ceil((skillNeed(t)-t.gauge)/skillRate(t))); }

