  const m=openModal(`<div class="ptitle">แลกของด้วยแต้มกาชา (มี ${S.gacha.points})</div><p class="c">ตัวละคร 4★ = 60 แต้ม • 5★ = 100 แต้ม (ได้ซ้ำแปลงเป็นเหรียญ)</p><div class="cgrid sm">${list.map(id=>cardHTML(id,{name:1})).join('')}</div>${btn('ปิด','gray','x')}`,'wide');
  $$('.ccard',m).forEach(c=>c.onclick=()=>{ const id=c.dataset.id, cost=CHAR[id].rar>=5?100:60; if(S.gacha.points<cost){ toast('แต้มไม่พอ'); AudioSys.sfx('error'); return;} S.gacha.points-=cost; const n=addChar(id); save(); AudioSys.jingle('star'); closeModal(m); showRewards([[n?'char_'+id:'medal_'+id,n?1:MEDAL_DUP[CHAR[id].rar]]]); after(); });
  $('[data-act=x]',m).onclick=()=>closeModal(m);
