// ================= SHOP =================
let shopTab='general';
function dailyOffers(seedKey,n){ let seed=0; for(const ch of seedKey) seed=(seed*31+ch.charCodeAt(0))>>>0; const rnd=()=>((seed=(seed*1103515245+12345)>>>0)/4294967296);
  const pool=[{k:'exp_m',n:10,cur:'gold',p:6000},{k:'exp_l',n:3,cur:'gold',p:9000},{k:'evo',n:3,cur:'gems',p:120},{k:'book',n:2,cur:'gold',p:12000},{k:'umedal',n:10,cur:'gems',p:150},{k:'gift',n:5,cur:'gold',p:5000},{k:'ticket',n:1,cur:'gems',p:250},{k:'bomb',n:3,cur:'gold',p:3000}];
  const out=[]; while(out.length<n){ const o=pool[Math.floor(rnd()*pool.length)]; if(!out.includes(o)) out.push(o);} return out; }
function qtyBox(max,priceOf,priceHTML){ return `<div class="qtyw"><div class="qrow"><button class="ibtn" data-q="-1">−</button><input type="number" class="qin" min="1" max="${max}" value="1"><button class="ibtn" data-q="+1">+</button></div><div class="qrow">${[10,50,100].map(n=>`<button class="btn blue sm" data-qs="${n}">${n}</button>`).join('')}<button class="btn purple sm" data-qs="max">MAX (${max})</button></div><p class="c qprice"></p></div>`; }
function bindQty(m,max,priceText,onChange){ const inp=$('.qin',m); const set=v=>{ v=Math.max(1,Math.min(max,Math.floor(+v||1))); inp.value=v; $('.qprice',m).innerHTML=priceText(v); onChange&&onChange(v); };
  $$('[data-q]',m).forEach(b=>b.onclick=()=>{ AudioSys.sfx('click'); set(+inp.value+ +b.dataset.q); });
  $$('[data-qs]',m).forEach(b=>b.onclick=()=>{ AudioSys.sfx('click'); set(b.dataset.qs==='max'?max:+b.dataset.qs); });
  inp.oninput=()=>{ if(inp.value!=='') set(inp.value); }; inp.onblur=()=>set(inp.value); set(1); return ()=>Math.max(1,Math.min(max,Math.floor(+inp.value||1))); }
function scrShop(){
  if(S.shop.daily!==today()){ S.shop.daily=today(); S.shop.dailyBought={}; } if(S.shop.weekly!==weekKey()){ S.shop.weekly=weekKey(); S.shop.weeklyBought={}; }
  const tabs=[['general','ทั่วไป'],['gold','Gold'],['gem','Gem'],['medal','เหรียญ'],['material','วัสดุ'],['costume','ชุด'],['event','กิจกรรม'],['vs','VS'],['daily','รายวัน'],['weekly','รายสัปดาห์']];
  const el=h(`<div class="screen mint">${topbar('ร้านค้า')}<div class="tabs shop">${tabs.map(([k,n])=>`<b data-t="${k}" class="${shopTab===k?'on':''}">${n}</b>`).join('')}</div>${walletHTML()}<div class="sgrid2" id="sitems"></div></div>`);
  ui.appendChild(el); bindCommon(el);
  $$('[data-t]',el).forEach(b=>b.onclick=()=>{ shopTab=b.dataset.t; AudioSys.sfx('tab'); go('shop'); });
  let items=[];
  const I=(k,n,cur,p,lim,limKey,label,icon)=>({k,n,cur,p,lim,limKey,label,icon});
  if(shopTab==='general') items=Object.keys(ITEMS).map(k=>I(k,1,'gold',ITEMS[k].price*30,0,0,ITEMS[k].n,null)).concat([I('gift',3,'gold',4000)]);
  if(shopTab==='gold') items=[I('gold',10000,'gems',50),I('gold',60000,'gems',250),I('gold',150000,'gems',550)];
  if(shopTab==='gem') items=[I('gems',100,'free',0,1,'freeGem','ของขวัญฟรีรายวัน 🎁'),I('gems',300,'gold',90000,3,'gemGold'),I('ticket',1,'gems',280)];
  if(shopTab==='energy') items=[I('stamina',30,'gems',30),I('stamina',100,'gems',90),I('stamina',30,'gold',15000,2,'stGold')];
  if(shopTab==='medal') items=[I('umedal',5,'gems',80),I('umedal',20,'gems',300),I('umedal',3,'gold',20000,3,'umGold')].concat(Object.keys(S.chars).slice(0,12).map(id=>I('medal_'+id,5,'umedal',5,0,0)));
  if(shopTab==='material') items=[I('exp_s',10,'gold',2000),I('exp_m',10,'gold',8000),I('exp_l',5,'gold',20000),I('evo',1,'gold',8000),I('evo',10,'gems',380),I('book',1,'gold',6000),I('book',5,'gems',200),I('gift',5,'gold',6000)];
  if(shopTab==='costume') items=CHARS.filter(c=>!S.chars[c.id]&&c.rar<=3).slice(0,10).map(c=>I('char_'+c.id,1,'costume',c.rar*8,0,0));
  if(shopTab==='event'){ items=items.concat(MARIO_SHOP.map((o,i)=>I(o.k,o.n,'cur_mario',o.p,0,0,i<2?'มาริโอ้':''))).concat(SPACE_SHOP.map((o,i)=>I(o.k,o.n,'cur_space',o.p,0,0,i<2?'อวกาศ':''))).concat(LOY_MINI_SHOP.map((o,i)=>I(o.k,o.n,'cur_loy',o.p,0,0,i<2?'ลอยกระทง':''))); for(const ev of EVENTS) items=items.concat(ev.shop.map(id=>I('char_'+id,1,'cur_'+ev.id,CHAR[id].rar*150,0,0))); }
  if(shopTab==='vs') items=[I('gems',100,'vscoin',40),I('gold',20000,'vscoin',20),I('ticket',1,'vscoin',60),I('stk',1,'vscoin',90),I('mtk',1,'vscoin',90),I('ltk',1,'vscoin',80),I('umedal',5,'vscoin',30),I('exp_l',3,'vscoin',40),I('evo',2,'vscoin',45),I('book',2,'vscoin',45)];
  if(shopTab==='daily') items=dailyOffers(today(),6).map((o,i)=>I(o.k,o.n,o.cur,Math.round(o.p*0.7),1,'d'+i,'ลด 30%'));
  if(shopTab==='weekly') items=dailyOffers(weekKey(),4).map((o,i)=>I(o.k,o.n*3,o.cur,Math.round(o.p*2),1,'w'+i,'แพ็กสัปดาห์'));
  const curIcon=c=>c==='vscoin'?`<img src="${src('vscoin')}">`:c==='gold'?`<img src="${src('coin')}">`:c==='gems'?`<img src="${src('gem')}">`:c==='umedal'?`<img src="${src('crown')}">`:c==='costume'?`<img src="${src('star')}">`:c.startsWith('cur_')?EVENTS.find(e=>e.id===c.slice(4)).curIcon:'';
  const have=c=>c==='gold'?S.gold:c==='gems'?S.gems:c==='free'?1:c.startsWith('cur_')?(S.eventCur[c.slice(4)]||0):(S.mat[c]||0);
  const bought=it=>it.lim&&(it.limKey==='freeGem'?S.shop.freeGem===today():(shopTab==='weekly'?S.shop.weeklyBought:S.shop.dailyBought)[it.limKey]>=it.lim);
  $('#sitems',el).innerHTML=items.map((it,i)=>`<div class="sitem ${bought(it)?'sold':''}" data-i="${i}">${it.k.startsWith('medal_')&&S.chars[it.k.slice(6)]?`<u class="own">มี ${S.chars[it.k.slice(6)].medal}</u>`:(S.mat[it.k]!==undefined&&!ITEMS[it.k])?`<u class="own">มี ${fmt(S.mat[it.k])}</u>`:ITEMS[it.k]?`<u class="own">มี ${S.items[it.k]||0}</u>`:''}${it.label?`<em>${it.label}</em>`:''}<div class="rws">${rewHTML(it.k,it.n)}</div><button class="btn ${it.cur==='free'?'pink':'yellow'} sm">${it.cur==='free'?'รับฟรี':curIcon(it.cur)+' '+fmt(it.p)}</button>${it.lim?`<small>จำกัด ${it.lim}</small>`:''}${shopTab!=='general'?'':''}</div>`).join('')+(shopTab==='event'?`<div class="evcur">${EVENTS.map(e=>`${e.curIcon} ${e.cur}: <b>${S.eventCur[e.id]||0}</b>`).join(' • ')}</div>`:'')+(shopTab==='costume'?`<div class="evcur">⭐ โทเคนชุด: <b>${S.mat.costume||0}</b> (ได้จากตู้ชิ้นส่วน)</div>`:'');
  $$('.sitem',el).forEach(d=>d.onclick=()=>{ const it=items[+d.dataset.i]; if(bought(it)){ toast('ซื้อครบแล้ว'); return; }
    if(it.k.startsWith('char_')&&S.chars[it.k.slice(5)]){ toast('มีตัวละครนี้แล้ว'); return; }
    if(have(it.cur)<it.p){ toast('ไม่พอ!'); AudioSys.sfx('error'); return; }
    const bk=shopTab==='weekly'?S.shop.weeklyBought:S.shop.dailyBought;
    const single=it.cur==='free'||it.k.startsWith('char_')||it.limKey==='freeGem';
    let max=single?1:Math.floor(have(it.cur)/Math.max(1,it.p)); if(it.lim&&!single) max=Math.min(max,it.lim-(bk[it.limKey]||0)); max=Math.max(1,Math.min(max,9999));
    const m=openModal(`<div class="ptitle">ยืนยันการซื้อ</div><div class="rws big">${rewHTML(it.k,it.n)}</div><p class="c">ราคาต่อชิ้น ${curIcon(it.cur)} ${fmt(it.p)} • มี ${curIcon(it.cur)} ${fmt(have(it.cur))}</p>${max>1?qtyBox(max):''}<div class="row c">${btn('ยกเลิก','gray','n')}${btn('ซื้อ','green','y')}</div>`);
    const getQ=max>1?bindQty(m,max,q=>`ซื้อ <b>${q}</b> ชิ้น = ได้ ${rewHTML(it.k,it.n*q)} • รวม ${curIcon(it.cur)} <b>${fmt(it.p*q)}</b>`):()=>1;
    $('[data-act=n]',m).onclick=()=>closeModal(m);
    $('[data-act=y]',m).onclick=()=>{ const q=getQ(), cost=it.p*q, c=it.cur; if(have(c)<cost){ toast('ไม่พอ!'); AudioSys.sfx('error'); return; }
      if(c==='gold') S.gold-=cost; else if(c==='gems') S.gems-=cost; else if(c.startsWith('cur_')) S.eventCur[c.slice(4)]-=cost; else if(c!=='free') S.mat[c]-=cost;
      if(it.limKey==='freeGem') S.shop.freeGem=today(); else if(it.lim){ bk[it.limKey]=(bk[it.limKey]||0)+q; }
      const g=grant({[it.k]:it.n*q}); AudioSys.sfx('buy'); closeModal(m); go('shop'); showRewards(g,q>1?`ซื้อสำเร็จ x${q}!`:'ซื้อสำเร็จ!'); };
  });
}

