let misTab='daily';
function scrMission(){
  resetPeriods();
  const el=h(`<div class="screen peach">${topbar('ภารกิจ')}<div class="tabs">${[['daily','รายวัน'],['weekly','รายสัปดาห์'],['main','หลัก'],['event','กิจกรรม'],['ach','ความสำเร็จ'],['beginner','มือใหม่']].map(([k,n])=>`<b data-t="${k}" class="${misTab===k?'on':''}">${n}</b>`).join('')}</div><div class="list" id="mlist"></div><div class="row c">${btn('รับทั้งหมด','green','all')}</div></div>`);
  ui.appendChild(el); bindCommon(el);
  $$('[data-t]',el).forEach(b=>b.onclick=()=>{ misTab=b.dataset.t; AudioSys.sfx('tab'); go('mission'); });
  let list=[], prog, claimed;
  if(misTab==='daily'){ list=MISSIONS.daily; prog=m=>S.daily.p[m.k]||0; claimed=S.daily.claimed; }
  if(misTab==='weekly'){ list=MISSIONS.weekly; prog=m=>S.weekly.p[m.k]||0; claimed=S.weekly.claimed; }
  if(misTab==='main'){ list=MISSIONS.main; prog=m=>{ const [w,s]=m.t.split('-'); return S.stages[`${w}-${s}-0`]?1:0; }; claimed=S.mainClaimed; list=list.map(x=>({...x,t2:1})); }
  if(misTab==='beginner'){ list=MISSIONS.beginner; prog=m=>statVal(m.k); claimed=S.begClaimed; }
  if(misTab==='ach'){ list=ACHIEVEMENTS.map(a=>a.k==='stage'?{...a,t2:1}:a); prog=m=>m.k==='stage'?(S.stages[m.t.split('-').concat('0').join('-')]?1:0):statVal(m.k); claimed=S.achClaimed; }
  if(misTab==='event'){ list=EVENTS.flatMap(e=>[{id:'ev_'+e.id+'1',n:`${e.name}: ผ่านด่านกิจกรรม 3 ด่าน`,k:'ev'+e.id,t:3,r:{['cur_'+e.id]:100,gems:50}},{id:'ev_'+e.id+'2',n:`${e.name}: ผ่านด่านกิจกรรม 5 (บอส)`,k:'evb'+e.id,t:1,r:{['cur_'+e.id]:300}}]);
    prog=m=>m.k.startsWith('evb')?(S.estages[m.k.slice(3)+'-5']?1:0):Object.keys(S.estages).filter(k=>k.startsWith(m.k.slice(2)+'-')).length; claimed=S.achClaimed; }
  const tgt=m=>m.t2||m.t;
  $('#mlist',el).innerHTML=list.map(m=>{ const p=Math.min(prog(m),tgt(m)), done=p>=tgt(m), cl=claimed[m.id]; return `<div class="mis ${cl?'claimed':''}" data-id="${m.id}"><div class="mic">${cl?'✅':done?'🎁':'📜'}</div><div class="mtx"><b>${m.n}</b><div class="xp"><i style="width:${p/tgt(m)*100}%"></i></div><small>${fmt(p)}/${fmt(tgt(m))}</small></div><div class="rws">${Object.entries(m.r).map(([k,v])=>rewHTML(k,v)).join('')}</div>${cl?'<span class="badge">รับแล้ว</span>':`<button class="btn ${done?'green':'gray'} sm" ${done?'':'disabled'}>รับ</button>`}</div>`; }).join('');
  const claim=m=>{ claimed[m.id]=true; return grant(m.r); };
  $$('.mis',el).forEach(d=>{ const b=$('button',d); if(b) b.onclick=()=>{ const m=list.find(x=>x.id===d.dataset.id); const g=claim(m); AudioSys.sfx('coin'); go('mission'); showRewards(g); }; });
  $('[data-act=all]',el).onclick=()=>{ let g=[]; for(const m of list){ if(!claimed[m.id]&&prog(m)>=tgt(m)) g=g.concat(claim(m)); } if(g.length){ go('mission'); showRewards(g);} else toast('ไม่มีภารกิจที่รับได้'); };
}

