// ===== MINI GAMES: Lucky Wheel / Honey Catch / Memory Match =====
'use strict';
function miniReset(){ if(!S.mini) S.mini={date:'',wheel:0,catch:0,memory:0,best:{}}; if(S.mini.date!==today()){ S.mini.date=today(); S.mini.wheel=0; S.mini.catch=0; S.mini.memory=0; S.mini.krathong=0; S.mini.rush=0; S.mini.shooter=0; } }
function miniUsed(k){ miniReset(); return S.mini[k]||0; }
function miniLeft(k){ return Math.max(0,MINI_LIMIT[k]-miniUsed(k)); }
function rollWheel(){ const tot=WHEEL.reduce((a,w)=>a+w.w,0); let r=Math.random()*tot; for(let i=0;i<WHEEL.length;i++){ r-=WHEEL[i].w; if(r<=0) return i; } return 0; }
function miniPrize(score){ // random bonus prize, better odds with higher score
  const out={}; if(Math.random()<Math.min(0.9,0.25+score/1200)){ const w=WHEEL[rollWheel()]; Object.assign(out,w.r); }
  if(score>=600 && Math.random()<0.35) out.ticket=(out.ticket||0)+1; return out; }
const MINI_GAMES=[
 {k:'wheel',n:'วงล้อนำโชค',ic:'stars',d:'หมุนวงล้อฟรีวันละครั้ง ลุ้นตั๋วกาชา เพชร และของรางวัลแบบสุ่ม',c:'#ffb21e'},
 {k:'catch',n:'หมีเก็บของขวัญ',ic:'chest',d:'เลื่อนหมีเก็บเหรียญ เพชร ตั๋ว หลบระเบิด 30 วินาที คะแนนยิ่งสูงยิ่งได้รางวัลเยอะ',c:'#ff7ab8'},
 {k:'memory',n:'จับคู่การ์ดคุมะ',ic:'crown',d:'เปิดการ์ดจับคู่ตัวละครให้ครบภายในเวลา ยิ่งเร็วยิ่งได้มาก',c:'#7b4fd6'}
];
function scrMini(){
  miniReset(); if(loyActive()&&!MINI_GAMES.find(g=>g.k==='krathong')) MINI_GAMES.unshift({k:'krathong',n:'ลอยกระทงอธิษฐาน (กิจกรรม)',ic:'loyi12',d:'บังคับกระทงล่องแม่น้ำ เก็บเทียน ดอกบัว ดอกมะลิ หลบขอนไม้และผีน้ำ แตะโคมลอย ได้ดอกบัวและตั๋วกาชาปอง',c:'#ff9a3a'});
  const el=h(`<div class="screen gachabg">${topbar('มินิเกม')}<div class="minis">${MINI_GAMES.map(g=>`<div class="minicard" style="--c:${g.c}">${icH(g.ic,'mbig')}<b>${g.n}</b><small>${g.d}</small><div class="mleft">เล่นได้วันนี้ <b>${miniLeft(g.k)}/${MINI_LIMIT[g.k]}</b></div>${S.mini.best[g.k]?`<small>สถิติสูงสุด: ${fmt(S.mini.best[g.k])}</small>`:''}<button class="btn ${miniLeft(g.k)?'yellow':'gray'} big" data-g="${g.k}">${miniLeft(g.k)?'เล่นเลย!':'พรุ่งนี้มาใหม่'}</button></div>`).join('')}</div>
   <div class="hint">รีเซ็ตจำนวนครั้งทุกวันตอนเที่ยงคืน • ของรางวัลสุ่ม: Gold, เพชร, ตั๋วกาชา, ยา EXP, เหรียญ, คริสตัล</div></div>`);
  ui.appendChild(el); bindCommon(el);
  $$('[data-g]',el).forEach(b=>b.onclick=()=>{ const k=b.dataset.g; if(!miniLeft(k)){ toast('ครบจำนวนครั้งแล้ววันนี้'); AudioSys.sfx('error'); return; } AudioSys.sfx('click'); ({wheel:playWheel,catch:playCatch,memory:playMemory,krathong:playKrathong,shooter:playShooter})[k](); });
}
function miniFinish(k,score,base){
  S.mini[k]++; S.mini.best[k]=Math.max(S.mini.best[k]||0,score); const r=Object.assign({},base); const pz=miniPrize(score); for(const x in pz) r[x]=(r[x]||0)+pz[x];
  const g=grant(r); save(true); go('minigame'); showRewards(g,'คะแนน '+fmt(score)+' — ได้รับรางวัล!');
}
// ---------- Lucky Wheel ----------
function playWheel(){
  const n=WHEEL.length, seg=360/n;
  const parts=WHEEL.map((w,i)=>{ const a0=(i*seg-90)*Math.PI/180,a1=((i+1)*seg-90)*Math.PI/180,r=150; return `<path d="M160 160 L${160+r*Math.cos(a0)} ${160+r*Math.sin(a0)} A${r} ${r} 0 0 1 ${160+r*Math.cos(a1)} ${160+r*Math.sin(a1)} Z" fill="${w.c}" stroke="#fff" stroke-width="4"/>`; }).join('');
  const labels=WHEEL.map((w,i)=>{ const a=(i+0.5)*seg; const [k,v]=Object.entries(w.r)[0]; const ik=REW_ICON[k]||'i77'; return `<g transform="rotate(${a} 160 160)"><image href="${src(ik)}" x="140" y="28" width="40" height="40"/><text x="160" y="86" text-anchor="middle" font-size="15" font-weight="700" fill="#5b34b0">x${v>=1000?Math.round(v/1000)+'k':v}</text></g>`; }).join('');
  const m=openModal(`<div class="ptitle">วงล้อนำโชค</div><div class="wheelbox"><div class="wptr">▼</div><svg id="wheel" viewBox="0 0 320 320" width="320" height="320">${parts}${labels}<circle cx="160" cy="160" r="30" fill="#fff" stroke="#ffb21e" stroke-width="6"/></svg></div><div class="row c">${btn('หมุน!','yellow big','spin')}</div>`,'nobg');
  $('[data-act=spin]',m).onclick=ev=>{ ev.target.disabled=true; const i=rollWheel(); const turns=360*6+(360-(i+0.5)*seg)+rand(-seg*0.35,seg*0.35);
    const w=$('#wheel',m); w.style.transition='transform 4.2s cubic-bezier(.15,.9,.2,1)'; w.style.transform=`rotate(${turns}deg)`;
    let tk=0; const tick=setInterval(()=>{ AudioSys.sfx('tab'); if(++tk>26) clearInterval(tick); },140);
    setTimeout(()=>{ AudioSys.jingle('gacha5'); S.mini.wheel++; const g=grant(WHEEL[i].r); save(true); closeModal(m); go('minigame'); showRewards(g,'วงล้อนำโชค!'); },4500); };
}
// ---------- Honey Catch ----------
function playCatch(){
  const m=openModal(`<div class="catchwrap"><canvas id="ccv" width="720" height="480"></canvas><div class="chud"><span id="csc">0</span><span id="ctm">30</span></div><div class="cmsg" id="cmsg">เลื่อนนิ้ว/เมาส์ เพื่อบังคับหมี<br>เก็บของ หลบระเบิด!<br><button class="btn yellow big" id="cgo">เริ่ม!</button></div></div>`,'nobg gfull');
  const cv2=$('#ccv',m), g=cv2.getContext('2d'); const W=720,H=480;
  const bear={x:W/2,w:110}; let items=[],score=0,time=30,run=false,stun=0,last=0,spawn=0,parts=[];
  const kinds=[{ic:'i74',p:10,w:40},{ic:'gem',p:30,w:16},{ic:'i77',p:20,w:20},{ic:'ticket',p:60,w:5},{ic:'i1',p:0,w:5,time:3},{ic:'i13',p:-40,w:18,bomb:1}];
  const tot=kinds.reduce((a,k)=>a+k.w,0);
  const move=e=>{ const r=cv2.getBoundingClientRect(); bear.x=clamp((e.clientX-r.left)/r.width*W,50,W-50); };
  cv2.addEventListener('pointermove',move); cv2.addEventListener('pointerdown',move);
  const bearImg=IMG.cls6;
  function frame(t){ if(!m.isConnected) return; const dt=Math.min(0.05,(t-last)/1000||0); last=t;
    if(run){ time-=dt; spawn-=dt; if(stun>0) stun-=dt;
      if(spawn<=0){ spawn=Math.max(0.22,0.6-(30-time)*0.012); let r=Math.random()*tot,k=kinds[0]; for(const x of kinds){ r-=x.w; if(r<=0){k=x;break;} } items.push({k,x:rand(30,W-30),y:-30,v:rand(160,260)+(30-time)*6,r:rand(-1,1)}); }
      for(const it of items){ it.y+=it.v*dt; it.r+=dt*2;
        if(it.y>H-110&&it.y<H-40&&Math.abs(it.x-bear.x)<bear.w/2&&stun<=0){ it.dead=true;
          if(it.k.bomb){ score=Math.max(0,score+it.k.p); stun=1; AudioSys.sfx('boom'); for(let i=0;i<14;i++) parts.push({x:it.x,y:it.y,vx:rand(-200,200),vy:rand(-250,-50),l:0.7,c:'#ff8a4a'}); }
          else { score+=it.k.p; if(it.k.time) time+=it.k.time; AudioSys.sfx(it.k.p>=30?'gem':'coin'); for(let i=0;i<8;i++) parts.push({x:it.x,y:it.y,vx:rand(-150,150),vy:rand(-220,-60),l:0.6,c:'#fff59a'}); } }
        if(it.y>H+40) it.dead=true; }
      items=items.filter(i=>!i.dead); if(time<=0){ run=false; end(); } }
    for(const p of parts){ p.l-=dt; p.vy+=500*dt; p.x+=p.vx*dt; p.y+=p.vy*dt; } parts=parts.filter(p=>p.l>0);
    const gr=g.createLinearGradient(0,0,0,H); gr.addColorStop(0,'#bfe6ff'); gr.addColorStop(1,'#ffe0f1'); g.fillStyle=gr; g.fillRect(0,0,W,H);
    g.fillStyle='#8fdc7a'; g.fillRect(0,H-36,W,36); g.fillStyle='#6cc45a'; for(let x=0;x<W;x+=24){ g.beginPath(); g.arc(x+12,H-36,12,Math.PI,0); g.fill(); }
    for(const it of items){ const im=IMG[it.k.ic]; const s=46; g.save(); g.translate(it.x,it.y); g.rotate(Math.sin(it.r)*0.3); g.drawImage(im,-s/2,-s/2*im.height/im.width,s,s*im.height/im.width); g.restore(); }
    const bh=110, bw=bearImg.width*bh/bearImg.height; g.save(); g.globalAlpha=stun>0&&Math.floor(stun*12)%2?0.4:1; g.drawImage(bearImg,bear.x-bw/2,H-40-bh,bw,bh); g.restore();
    for(const p of parts){ g.globalAlpha=Math.max(0,p.l*1.5); g.fillStyle=p.c; g.beginPath(); g.arc(p.x,p.y,5,0,7); g.fill(); } g.globalAlpha=1;
    $('#csc',m).textContent='คะแนน '+score; $('#ctm',m).textContent='เวลา '+Math.max(0,Math.ceil(time));
    requestAnimationFrame(frame); }
  requestAnimationFrame(frame);
  $('#cgo',m).onclick=()=>{ $('#cmsg',m).style.display='none'; run=true; AudioSys.sfx('wave'); };
  function end(){ AudioSys.jingle('win'); setTimeout(()=>{ closeModal(m); miniFinish('catch',score,{gold:score*15,gems:Math.floor(score/150)*10,exp_s:Math.floor(score/120)}); },700); }
}
// ---------- Memory Match ----------
function playMemory(){
  const pool=CHARS.map(c=>c.id).sort(()=>Math.random()-0.5).slice(0,8); const deck=[...pool,...pool].sort(()=>Math.random()-0.5);
  let open=[],matched=0,moves=0,time=60,lock=false,timer=null,started=false;
  const m=openModal(`<div class="ptitle">จับคู่การ์ดคุมะ</div><div class="memhud"><span id="mt">เวลา 60</span><span id="mm">เปิด 0 ครั้ง</span></div><div class="memgrid">${deck.map((id,i)=>`<div class="mcard" data-i="${i}"><div class="mf front"><img src="${src('i77')}"></div><div class="mf back"><img src="${src(CHAR[id].img)}"></div></div>`).join('')}</div>`,'nobg');
  const cards=$$('.mcard',m);
  const end=win=>{ clearInterval(timer); const score=win?Math.round(300+time*20-moves*4):matched*40; AudioSys.jingle(win?'win':'lose'); setTimeout(()=>{ closeModal(m); miniFinish('memory',Math.max(0,score),{gold:Math.max(500,score*12),gems:win?30:0,exp_m:win?2:0}); },900); };
  cards.forEach(c=>c.onclick=()=>{ const i=+c.dataset.i; if(lock||c.classList.contains('flip')) return;
    if(!started){ started=true; timer=setInterval(()=>{ time--; $('#mt',m).textContent='เวลา '+time; if(time<=0) end(false); },1000); }
    c.classList.add('flip'); AudioSys.sfx('tab'); open.push(i);
    if(open.length===2){ moves++; $('#mm',m).textContent='เปิด '+moves+' ครั้ง'; const [a,b2]=open; open=[];
      if(deck[a]===deck[b2]){ matched++; AudioSys.sfx('coin'); cards[a].classList.add('ok'); cards[b2].classList.add('ok'); if(matched===8) end(true); }
      else { lock=true; setTimeout(()=>{ cards[a].classList.remove('flip'); cards[b2].classList.remove('flip'); lock=false; },650); } } });
}
// ---------- Loy Krathong: steer the krathong down the river ----------
function playKrathong(){
  const m=openModal(`<div class="catchwrap"><canvas id="kcv" width="720" height="480"></canvas><div class="chud"><span id="ksc">0</span><span id="klv"></span><span id="ktm">45</span></div>
    <div class="cmsg" id="kmsg"><b style="font-size:28px">ลอยกระทงอธิษฐาน</b><span style="font-size:17px">เลื่อนนิ้ว/เมาส์บังคับกระทง • เก็บเทียน ดอกบัว ดอกมะลิ<br>หลบขอนไม้และผีน้ำ (ไฟเทียนดับ 3 ครั้ง = จบ)<br>แตะโคมลอยบนฟ้าเพื่อคะแนนพิเศษ!</span><button class="btn yellow big" id="kgo">ลอยกระทง!</button></div></div>`,'nobg gfull');
  const cv2=$('#kcv',m), g=cv2.getContext('2d'); const W=720,H=480;
  const boat={x:W/2,tx:W/2}; let items=[],lanterns=[],parts=[],score=0,time=45,lives=3,run=false,last=0,spawn=0,lspawn=0,inv=0,flow=0,combo=0;
  const good=[{ic:'loyi27',p:10,w:30,n:'เทียน'},{ic:'loyi18',p:20,w:18,n:'ดอกบัว'},{ic:'loyi34',p:15,w:20,n:'มะลิ'},{ic:'i74',p:10,w:14},{ic:'loyi0',p:80,w:2,tk:1}];
  const bad=[{ic:'loym3',bad:1,w:8},{ic:'loym8',bad:1,w:6},{log:1,bad:1,w:12}];
  const pool=[...good,...bad], tot=pool.reduce((a,k)=>a+k.w,0);
  const pt=e=>{ const r=cv2.getBoundingClientRect(); return {x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H}; };
  cv2.addEventListener('pointermove',e=>{ boat.tx=clamp(pt(e).x,40,W-40); });
  cv2.addEventListener('pointerdown',e=>{ const p=pt(e); for(const l of lanterns){ if(!l.hit&&Math.hypot(l.x-p.x,l.y-p.y)<34){ l.hit=1; score+=30; AudioSys.sfx('gem'); for(let i=0;i<14;i++) parts.push({x:l.x,y:l.y,vx:rand(-160,160),vy:rand(-160,60),l:0.8,c:pick(['#ffd36b','#ff9a3a','#fff'])}); return; } } boat.tx=clamp(p.x,40,W-40); });
  let tkGot=0;
  function frame(t){ if(!m.isConnected) return; const dt=Math.min(0.05,(t-last)/1000||0); last=t; flow+=dt;
    if(run){ time-=dt; spawn-=dt; lspawn-=dt; if(inv>0) inv-=dt; const sp=150+(45-time)*4;
      boat.x+=(boat.tx-boat.x)*Math.min(1,dt*9);
      if(spawn<=0){ spawn=Math.max(0.28,0.75-(45-time)*0.01); let r=Math.random()*tot,k=pool[0]; for(const x of pool){ r-=x.w; if(r<=0){k=x;break;} } items.push({k,x:rand(50,W-50),y:-40,v:sp*rand(0.85,1.15),r:rand(0,6)}); }
      if(lspawn<=0){ lspawn=rand(1.6,3); lanterns.push({x:rand(60,W-60),y:H+30,v:rand(40,70),ph:rand(0,6)}); }
      for(const it of items){ it.y+=it.v*dt; it.r+=dt; it.x+=Math.sin(flow*1.5+it.r)*14*dt;
        if(!it.dead && Math.abs(it.y-(H-70))<34 && Math.abs(it.x-boat.x)<46){ it.dead=1;
          if(it.k.bad){ if(inv<=0){ lives--; inv=1.2; combo=0; AudioSys.sfx('leak'); for(let i=0;i<12;i++) parts.push({x:boat.x,y:H-80,vx:rand(-150,150),vy:rand(-200,-40),l:0.6,c:'#9fb4c8'}); if(lives<=0){ run=false; end(); } } }
          else { combo++; const p=Math.round(it.k.p*(1+Math.min(1,combo/20))); score+=p; if(it.k.tk) tkGot++; AudioSys.sfx(it.k.p>=20?'gem':'coin'); for(let i=0;i<8;i++) parts.push({x:it.x,y:it.y,vx:rand(-120,120),vy:rand(-200,-60),l:0.6,c:pick(['#fff59a','#ff9ad5'])}); } }
        if(it.y>H+50) it.dead=1; }
      for(const l of lanterns){ l.y-=l.v*dt; l.ph+=dt; l.x+=Math.sin(l.ph)*12*dt; }
      items=items.filter(i=>!i.dead); lanterns=lanterns.filter(l=>!l.hit&&l.y>-60);
      if(time<=0){ run=false; end(); } }
    for(const p of parts){ p.l-=dt; p.vy+=380*dt; p.x+=p.vx*dt; p.y+=p.vy*dt; } parts=parts.filter(p=>p.l>0);
    // draw river at night
    const gr=g.createLinearGradient(0,0,0,H); gr.addColorStop(0,'#1a1850'); gr.addColorStop(1,'#2c4f9e'); g.fillStyle=gr; g.fillRect(0,0,W,H);
    const moon=IMG.loyi45; if(moon) g.drawImage(moon,W-170,10,140,176);
    g.strokeStyle='rgba(180,210,255,0.25)'; g.lineWidth=2; for(let i=0;i<14;i++){ const y=((flow*90+i*40)%(H+40))-20; g.beginPath(); g.moveTo(80+Math.sin(i)*30,y); g.quadraticCurveTo(W/2,y+8,W-80+Math.cos(i)*30,y); g.stroke(); }
    g.fillStyle='#2e6b3a'; g.fillRect(0,0,34,H); g.fillRect(W-34,0,34,H); const lt=IMG.loyi27; for(let y=(flow*90)%80-80;y<H;y+=80){ if(lt){ g.drawImage(lt,4,y,28,30); g.drawImage(lt,W-32,y+40,28,30);} }
    for(const l of lanterns){ g.save(); g.globalCompositeOperation='lighter'; const rg=g.createRadialGradient(l.x,l.y,0,l.x,l.y,40); rg.addColorStop(0,'rgba(255,190,90,0.7)'); rg.addColorStop(1,'rgba(255,190,90,0)'); g.fillStyle=rg; g.fillRect(l.x-40,l.y-40,80,80); g.restore(); const im=IMG.loyi13; if(im) g.drawImage(im,l.x-22,l.y-26,44,52); }
    for(const it of items){ g.save(); g.translate(it.x,it.y); g.rotate(Math.sin(it.r*2)*0.15);
      if(it.k.log){ g.fillStyle='#7a4f2a'; g.strokeStyle='#4a2c12'; g.lineWidth=3; g.beginPath(); g.roundRect?g.roundRect(-44,-13,88,26,13):g.rect(-44,-13,88,26); g.fill(); g.stroke(); g.fillStyle='#c4925a'; g.beginPath(); g.ellipse(44,0,8,12,0,0,7); g.fill(); }
      else { const im=IMG[it.k.ic]; const s=it.k.bad?62:42; g.drawImage(im,-s/2,-s/2*im.height/im.width,s,s*im.height/im.width); }
      g.restore(); }
    const kb=IMG.loyi12; const kw=96, kh=kb.height*kw/kb.width; g.save(); g.globalAlpha=inv>0&&Math.floor(inv*12)%2?0.4:1; g.drawImage(kb,boat.x-kw/2,H-70-kh/2+Math.sin(flow*3)*3,kw,kh); g.restore();
    g.save(); g.globalCompositeOperation='lighter'; const kg=g.createRadialGradient(boat.x,H-90,0,boat.x,H-90,70); kg.addColorStop(0,'rgba(255,220,120,0.5)'); kg.addColorStop(1,'rgba(255,220,120,0)'); g.fillStyle=kg; g.fillRect(boat.x-70,H-160,140,140); g.restore();
    for(const p of parts){ g.globalAlpha=Math.max(0,p.l*1.5); g.fillStyle=p.c; g.beginPath(); g.arc(p.x,p.y,4,0,7); g.fill(); } g.globalAlpha=1;
    $('#ksc',m).textContent='คะแนน '+score+(combo>4?' (x'+combo+')':''); $('#ktm',m).textContent='เวลา '+Math.max(0,Math.ceil(time)); $('#klv',m).textContent='ไฟเทียน '+'🕯'.repeat(Math.max(0,lives));
    requestAnimationFrame(frame); }
  requestAnimationFrame(frame);
  $('#kgo',m).onclick=()=>{ $('#kmsg',m).style.display='none'; run=true; AudioSys.sfx('wave'); };
  function end(){ AudioSys.jingle('win'); setTimeout(()=>{ closeModal(m); S.mini.krathong=(S.mini.krathong||0)+1; S.mini.best.krathong=Math.max(S.mini.best.krathong||0,score);
    const r={cur_loy:Math.round(score/4),gold:score*10}; const tk=tkGot+(score>=500?1:0)+(score>=900?1:0); if(tk) r.ltk=tk;
    const gg=grant(r); save(true); go('event'); showRewards(gg,'ลอยกระทงได้ '+fmt(score)+' คะแนน!'); },700); }
}

