function mvpTick(e,dt){
  const bd=BOSSES[e.boss]; e.mt=(e.mt||0)+dt;
  const every=s=>{ if(e.mt>=s){ e.mt=0; return true;} return false; };
  switch(bd.mvp){
    case 'heads': if(every(7)){ const c=towersNear(e.x,e.y,3000).sort(()=>Math.random()-0.5).slice(0,3); for(const t of c) B.tele.push({k:'burnT',t,src:{x:e.x,y:e.y-60},time:0,max:0.9,dur:4,boss:true,img:PROJ_IMG.fire}); } break;
    case 'blessing': if(every(8)){ for(const o of B.enemies) if(!o.dead&&!o.boss&&Math.hypot(o.x-e.x,o.y-e.y)<260) o.shield=Math.max(o.shield,o.maxHp*0.3); burst(e.x,e.y-60,20,['#ffd23a','#fff'],'star',240); } break;
    case 'armor': if(every(7)){ e.armorUp=4; floatText(e.x,e.y-150,'เกราะคริสตัล!','#d6c8ff',22,false,'spikeShield'); } break;
    case 'missile': e.st.slow=null; if(e.st.freeze>0.4) e.st.freeze=0.4; if(e.st.root>0.4) e.st.root=0.4; if(every(6)){ B.debuffGate=0; castEnemySkill(e,'bossShot'); } break;
    case 'summon': if(every(10)){ for(let i=0;i<2;i++) spawnEnemy({id:pick(B.cfg.pool.slice(0,6)),elite:true,hp:215*Math.pow(1.08,B.cfg.g-1)*B.cfg.diff,d:Math.max(0,e.d-30-i*30),pi:e.pi}); burst(e.x,e.y-60,24,['#a571ff','#fff'],'star',260); } break;
    case 'web': if(every(7)){ const c=towersNear(e.x,e.y,3000).sort(()=>Math.random()-0.5).slice(0,2); for(const t of c) B.tele.push({k:'web',t,src:{x:e.x,y:e.y-60},time:0,max:0.9,dur:6,boss:true}); } break;
    case 'steal': if(every(9)){ const a=Math.min(B.energy,100); B.energy-=a; floatText(e.x,e.y-150,'-'+a+' Energy','#ffe36b',22,true,'bag'); } break;
  }
}

