function playShooter(){
  const m=openModal(`<div class="catchwrap"><canvas id="scv" width="760" height="460"></canvas><div class="chud"><span id="ssc">0</span><span id="slv"></span><span id="stm">60</span></div>
    <div class="cmsg" id="smsg"><b style="font-size:28px">ยานคุมะตะลุยอวกาศ</b><span style="font-size:17px">เลื่อนนิ้ว/เมาส์ขึ้นลงเพื่อบังคับ • ยิงอัตโนมัติ<br>เก็บดาวเพิ่มพลังยิง • เก็บหัวใจเพิ่มชีวิต • ชีวิต 3 ดวง<br>วินาทีที่ 40 บอส MVP จะปรากฏ!</span><button class="btn yellow big" id="sgo">ออกบิน!</button></div></div>`,'nobg gfull');
  const cv2=$('#scv',m), g=cv2.getContext('2d'); const W=760,H=460;
  const P={x:110,y:H/2,ty:H/2,inv:0,cd:0,pow:0}; let bul=[],eb=[],foes=[],items=[],parts=[],stars=[],score=0,time=60,lives=3,run=false,last=0,spawn=0,boss=null,bossDone=false,tk=0,el=0;
  for(let i=0;i<70;i++) stars.push({x:Math.random()*W,y:Math.random()*H,s:Math.random()*2+0.5,v:Math.random()*60+30});
  const FOES=['spm7','spm8','spm9','spm10','spm20','spm18','spm11','spm27','spm24','spm12','spm22','spm26'];
  const pt=e=>{ const r=cv2.getBoundingClientRect(); return {x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H}; };
  cv2.addEventListener('pointermove',e=>{ const p=pt(e); P.ty=clamp(p.y,30,H-30); }); cv2.addEventListener('pointerdown',e=>{ const p=pt(e); P.ty=clamp(p.y,30,H-30); });
  const boom=(x,y,c,n=12)=>{ for(let i=0;i<n;i++) parts.push({x,y,vx:rand(-200,200),vy:rand(-200,200),l:0.6,c:c||pick(['#ffe36b','#ff9ad5','#9fe8ff'])}); };
  const hitP=()=>{ if(P.inv>0) return; lives--; P.inv=1.5; P.pow=0; AudioSys.sfx('leak'); boom(P.x,P.y,'#ff5f7a',18); if(lives<=0){ run=false; end(); } };
  function frame(t){ if(!m.isConnected) return; const dt=Math.min(0.05,(t-last)/1000||0); last=t;
    for(const s of stars){ s.x-=s.v*dt*(run?1:0.3); if(s.x<0){ s.x=W; s.y=Math.random()*H; } }
    if(run){ time-=dt; el+=dt; spawn-=dt; P.cd-=dt; if(P.inv>0) P.inv-=dt; if(P.pow>0) P.pow-=dt;
      P.y+=(P.ty-P.y)*Math.min(1,dt*10);
      if(P.cd<=0){ P.cd=0.17; AudioSys.sfx('shoot_bullet'); bul.push({x:P.x+30,y:P.y,vy:0}); if(P.pow>0){ bul.push({x:P.x+30,y:P.y,vy:-160}); bul.push({x:P.x+30,y:P.y,vy:160}); } }
      if(!boss&&spawn<=0){ spawn=Math.max(0.35,1.1-el*0.012); const big=Math.random()<0.15; foes.push({img:pick(FOES),x:W+40,y:rand(40,H-40),hp:big?6:2,mx:big?6:2,v:rand(110,190)+el*2,ph:rand(0,6),wob:Math.random()<0.5,sh:Math.random()<0.35,scd:rand(1,2.5),s:big?70:50}); }
      if(el>=40&&!boss&&!bossDone){ boss={img:pick(['spm55','spm56','spm57','spm58','spm59','spm60','spm54']),x:W+120,y:H/2,hp:70,mx:70,scd:1.2,ph:0}; AudioSys.sfx('boss'); }
      for(const b of bul){ b.x+=640*dt; b.y+=b.vy*dt; }
      for(const f of foes){ f.x-=f.v*dt; f.ph+=dt*3; if(f.wob) f.y+=Math.sin(f.ph)*80*dt; if(f.sh){ f.scd-=dt; if(f.scd<=0){ f.scd=2.2; const a=Math.atan2(P.y-f.y,P.x-f.x); eb.push({x:f.x,y:f.y,vx:Math.cos(a)*220,vy:Math.sin(a)*220}); } }
        if(Math.hypot(f.x-P.x,f.y-P.y)<f.s*0.6){ f.dead=1; hitP(); boom(f.x,f.y); } if(f.x<-60) f.dead=1; }
      if(boss){ boss.ph+=dt; boss.x=Math.max(W-130,boss.x-80*dt); boss.y=H/2+Math.sin(boss.ph*1.2)*150; boss.scd-=dt;
        if(boss.scd<=0){ boss.scd=boss.hp<35?0.9:1.3; for(let i=-2;i<=2;i++){ const a=Math.PI+i*0.22; eb.push({x:boss.x-50,y:boss.y,vx:Math.cos(a)*240,vy:Math.sin(a)*240}); } } }
      for(const b of bul){ for(const f of foes){ if(!f.dead&&!b.dead&&Math.abs(b.x-f.x)<f.s*0.55&&Math.abs(b.y-f.y)<f.s*0.55){ b.dead=1; f.hp--; if(f.hp<=0){ f.dead=1; score+=f.mx>2?40:10; AudioSys.sfx('pop'); boom(f.x,f.y); const r=Math.random(); if(r<0.12) items.push({k:'star',x:f.x,y:f.y}); else if(r<0.16) items.push({k:'heart',x:f.x,y:f.y}); else if(r<0.19) items.push({k:'tk',x:f.x,y:f.y}); } } }
        if(boss&&!b.dead&&Math.abs(b.x-boss.x)<70&&Math.abs(b.y-boss.y)<80){ b.dead=1; boss.hp--; AudioSys.sfx('hit'); if(boss.hp<=0){ score+=300; tk++; boom(boss.x,boss.y,null,60); AudioSys.sfx('boom'); AudioSys.jingle('gacha5'); boss=null; bossDone=true; } } }
      for(const e of eb){ e.x+=e.vx*dt; e.y+=e.vy*dt; if(Math.hypot(e.x-P.x,e.y-P.y)<18){ e.dead=1; hitP(); } }
      for(const it of items){ it.x-=120*dt; if(Math.hypot(it.x-P.x,it.y-P.y)<34){ it.dead=1; if(it.k==='star'){ P.pow=8; score+=20; AudioSys.sfx('gem'); } else if(it.k==='heart'){ lives=Math.min(5,lives+1); AudioSys.sfx('heal'); } else { tk++; AudioSys.sfx('gacha_rare'); } } }
      bul=bul.filter(b=>!b.dead&&b.x<W+20&&b.y>-20&&b.y<H+20); foes=foes.filter(f=>!f.dead); eb=eb.filter(e=>!e.dead&&e.x>-20&&e.x<W+20&&e.y>-20&&e.y<H+20); items=items.filter(i=>!i.dead&&i.x>-30);
      if(time<=0){ run=false; end(); } }
    for(const p of parts){ p.l-=dt; p.x+=p.vx*dt; p.y+=p.vy*dt; } parts=parts.filter(p=>p.l>0);
    const gr=g.createLinearGradient(0,0,W,H); gr.addColorStop(0,'#160f3e'); gr.addColorStop(1,'#3b1d6e'); g.fillStyle=gr; g.fillRect(0,0,W,H);
    for(const s of stars){ g.fillStyle=`rgba(255,255,255,${0.4+s.s/4})`; g.fillRect(s.x,s.y,s.s,s.s); }
    const pl=IMG.spf8; if(pl) g.drawImage(pl,W-200-((el*15)%(W+300))+300,60,110,84);
    const di=(k,x,y,s,a)=>{ const im=IMG[k]; if(!im) return; const w=s, hh=im.height*s/im.width; g.save(); if(a!==undefined) g.globalAlpha=a; g.drawImage(im,x-w/2,y-hh/2,w,hh); g.restore(); };
    for(const it of items) di(it.k==='star'?'spf11':it.k==='heart'?'i1':'spg0',it.x,it.y,36);
    for(const f of foes){ g.save(); g.translate(f.x,f.y); g.scale(-1,1); di(f.img,0,0,f.s); g.restore(); if(f.mx>2){ g.fillStyle='#ff5f7a'; g.fillRect(f.x-25,f.y-f.s/2-8,50*f.hp/f.mx,5); } }
    if(boss){ g.save(); g.globalCompositeOperation='lighter'; const rg=g.createRadialGradient(boss.x,boss.y,0,boss.x,boss.y,110); rg.addColorStop(0,'rgba(255,120,200,0.5)'); rg.addColorStop(1,'rgba(255,120,200,0)'); g.fillStyle=rg; g.fillRect(boss.x-110,boss.y-110,220,220); g.restore(); di(boss.img,boss.x,boss.y,160); g.fillStyle='#3a1530'; g.fillRect(W/2-150,14,300,12); g.fillStyle='#ff4f7b'; g.fillRect(W/2-150,14,300*boss.hp/boss.mx,12); g.fillStyle='#fff'; g.font='bold 13px sans-serif'; g.textAlign='center'; g.fillText('MVP BOSS',W/2,40); }
    g.fillStyle='#fff59a'; for(const b of bul){ g.beginPath(); g.ellipse(b.x,b.y,9,4,0,0,7); g.fill(); }
    g.fillStyle='#ff6fae'; for(const e of eb){ g.beginPath(); g.arc(e.x,e.y,6,0,7); g.fill(); }
    if(run||P.inv<=0) di('sp4',P.x,P.y,70,P.inv>0&&Math.floor(P.inv*12)%2?0.35:1);
    g.save(); g.globalCompositeOperation='lighter'; g.fillStyle='rgba(255,180,80,0.7)'; g.beginPath(); g.ellipse(P.x-40,P.y+14,12+Math.random()*6,6,0,0,7); g.fill(); g.restore();
    for(const p of parts){ g.globalAlpha=Math.max(0,p.l*1.6); g.fillStyle=p.c; g.beginPath(); g.arc(p.x,p.y,4,0,7); g.fill(); } g.globalAlpha=1;
    $('#ssc',m).textContent='คะแนน '+score; $('#stm',m).textContent='เวลา '+Math.max(0,Math.ceil(time)); $('#slv',m).textContent='❤'.repeat(Math.max(0,lives))+(P.pow>0?'  ⭐x3':'');
    requestAnimationFrame(frame); }
  requestAnimationFrame(frame);
  $('#sgo',m).onclick=()=>{ $('#smsg',m).style.display='none'; run=true; AudioSys.sfx('wave'); };
  function end(){ AudioSys.jingle(bossDone?'win':'lose'); setTimeout(()=>{ closeModal(m); S.mini.shooter=(S.mini.shooter||0)+1; S.mini.best.shooter=Math.max(S.mini.best.shooter||0,score);
    const r={cur_space:Math.round(score/4),gold:score*10}; const t2=tk+(score>=600?1:0); if(t2) r.stk=t2; const gg=grant(r); save(true); go('event'); showRewards(gg,'บินได้ '+fmt(score)+' คะแนน!'); },700); }
}

