const VS_TIERS=[['Bronze',0,'#c98a52'],['Silver',300,'#b8c4d6'],['Gold',700,'#ffc93a'],['Platinum',1200,'#6fe0d0'],['Diamond',1800,'#7cc4ff'],['Master',2500,'#c58bff'],['Legendary',3300,'#ff6fa8']];
