function vsWaveList(w){ // deterministic composition
  const L=[]; const n=Math.min(28,Math.round(6+w*1.3));
  for(let i=0;i<n;i++){ let k='slime';
    if(w<=3) k=i%3===2?'speed':'slime';
    else if(w<=6) k=['slime','speed','tank','shield','slime','speed'][i%6];
    else if(w<=9) k=['poison','fly','freeze','bomb','tank','heal','shield','split','ghost','speed'][i%10];
    else k=['tank','shield','golem','fly','poison','freeze','heal','bomb','thief','split','ghost','speed','swarm','elite'][i%14];
    L.push(k); }
  if(w>=7&&w%2===1) L.push('elite'); if(w===10) L.push('boss'); else if(w>10&&w%3===1) L.push(w%2?'iceboss':'boss');
  return L;
}
