function vsLoop(G,now){ if(!G.running||VSG!==G) return; requestAnimationFrame(t=>vsLoop(G,t));
  const dt=Math.min(0.05,(now-G.lastT)/1000); G.lastT=now; G.shake=Math.max(0,(G.shake||0)-dt*1.5);
  if(G.countdown>0){ const before=Math.ceil(G.countdown); G.countdown-=dt; if(Math.ceil(G.countdown)!==before&&G.countdown>0) AudioSys.sfx('tab'); if(G.countdown<=0){ AudioSys.sfx('wave'); G.t0=performance.now(); } }
  else if(!G.over&&G.coop){ if(G.isG){ G.t=(now-(G.t0||now))/1000; vsGhostTick(G.me,dt); }
    else { G.t=(now-(G.t0||now))/1000; vsSim(G.me,dt,G); if(G.av){ if(G.isB||G.partnerLeft){ if(G.myOwn===0) vsAvMonBot(G.me,dt,G); else vsCoopBot(G.me,dt,G,0); } } else if(G.isB||G.partnerLeft) vsCoopBot(G.me,dt,G,1);
      if(G.isH){ G.snapT-=dt; if(G.snapT<=0){ G.snapT=0.08; vsSendNet(vsCoopSnap(G)); } }
      if(G.av){ if(G.me.hp<=0) vsAvEnd(G,1,'ฐานแตก! ฝั่งมอนบุกสำเร็จ 👾'); else if(G.t>=AV_TIME) vsAvEnd(G,0,'ป้องกันครบ 6 นาที! ฝั่งฮีโร่ชนะ 🧸'); }
      else if(G.me.hp<=0) vsCoopEnd(G,'ฐานถูกทำลาย! ไปถึง Wave '+G.me.wave); } }
  else if(G.coop){ if(G.isG) vsGhostTick(G.me,dt); }
  else if(!G.over){ G.t=(now-(G.t0||now))/1000; const toMe=k=>vsSpawn(G.me,k,true,G);
    vsSim(G.me,dt,G);
    if(G.mode==='bot'){ vsSim(G.opp,dt,G); vsBot(G.opp,dt,G,toMe); } else vsGhostTick(G.opp,dt);
    if(G.mode==='net'){ G.snapT-=dt; if(G.snapT<=0){ G.snapT=0.08; vsSendNet(vsSnap(G.me)); } }
    if(G.me.hp<=0){ if(G.mode==='net') vsSendNet({t:'dead'}); vsEnd(G,'lose','ฐานของคุณถูกทำลาย'); }
    else if(G.mode==='bot'&&G.opp.hp<=0) vsEnd(G,'win','ทำลายฐานบอทสำเร็จ!');
    else if(G.t>=VS_TIME){ if(G.mode==='net'&&!VSN.host){ G.waitRes=(G.waitRes||0)+dt; if(G.waitRes>3) vsTimeUp(G,true); } else vsTimeUp(G); }
  } else { if(G.mode!=='bot') vsGhostTick(G.opp,dt); }
  vsRender(G); perfTick(dt); if(now-(G.hudT||0)>100||G.over){ G.hudT=now; if(G.coop) vsCoopHud(G); else vsHud(G); }
}
