  if(G.sel){ for(const p of me.pads){ if(p.u||(G.coop&&p.own!==G.myOwn)) continue; const pr=1+Math.sin(T*6)*0.08; c.save(); c.globalCompositeOperation='lighter'; vsGlow(c,p.x,p.y,70*pr,'rgba(255,240,140,0.9)',0.6); c.restore(); c.strokeStyle='#fff'; c.lineWidth=4; c.setLineDash([10,8]); c.lineDashOffset=-T*30; c.beginPath(); c.ellipse(p.x,p.y,52*pr,34*pr,0,0,7); c.stroke(); c.setLineDash([]); } }
