    for(const f of F.fx) vsDrawFx(c,f,F); for(const t of F.texts){ c.save(); c.globalAlpha=1-t.a; c.font=`900 ${t.s}px system-ui,sans-serif`; c.textAlign='center'; c.lineWidth=5; c.strokeStyle='rgba(40,20,60,0.85)'; const y=t.y-t.a*40; c.strokeText(t.t,t.x,y); c.fillStyle=t.c; c.fillText(t.t,t.x,y); c.restore(); }
