function marioStages(w){ return MARIO_WORLD[w].dots.length; }
function marioMapId(w,s){ return 'mw'+w+'_'+(((s-1)%4)+1); }
function marioBoss(w,s){ if(w===9) return W9_BOSS[s]||null; const n=marioStages(w); if(s===n) return MW[w].boss; if(s===Math.ceil(n/2)) return null; return null; }
function marioG(w,s){ return 6+(w-1)*5+s; }
function marioCfg(opt){ const w=opt.mw, s=opt.stage, W=MW[w]; const g=marioG(w,s); const elite=s===Math.ceil(marioStages(w)/2);
  return {map:marioMapId(w,s),bg:W.bg,title:`มาริโอ้ World ${w}-${s} ${W.th}`,cfg:{pool:W.pool,nW:5+Math.ceil(s/2)+(w>=7?1:0),g,diff:1,stage:Math.min(10,s+Math.floor(w/3)),bossA:marioBoss(w,s)||(elite&&w<9?'mk_'+['','larry','morton','wendy','iggy','roy','lemmy','ludwig','jr'][Math.max(1,w-1)]:null)}}; }
const _stageInfo=stageInfo;
stageInfo=function(opt){ if(!opt.mw) return _stageInfo(opt); const c=marioCfg(opt); const W=MW[opt.mw];
  return {map:c.map,pool:W.pool.slice(0,Math.min(W.pool.length,opt.stage+3)),boss:c.cfg.bossA?[c.cfg.bossA]:[],cost:6,name:c.title,g:c.cfg.g,rec:Math.round(1500*Math.pow(1.075,c.cfg.g))}; };
function marioUnlocked(w,s){ S.mario=S.mario||{chest:{}}; if(w===1&&s===1) return true;
  if(s===1) return !!S.estages[`mario-${w-1}-${marioStages(w-1)}`]; if(!S.estages[`mario-${w}-${s-1}`]) return false;
  const q=MARIO_WORLD[w].qAfter; if(s===q+1&&!S.mario.chest[w]) return 'chest'; return true; }
function marioStars(w){ let t=0; for(let s=1;s<=marioStages(w);s++){ const r=S.estages[`mario-${w}-${s}`]; t+=r?r.stars:0; } return t; }

