// ---------- screen: curtain intro + world select ----------
let marioSeenIntro=false;
function scrMario(arg){
  arg=arg||{}; S.mario=S.mario||{chest:{}}; AudioSys.setMode('menu'); AudioSys.setStyle&&AudioSys.setStyle('mario');
  const walkers=['mh4_0','mh4_1','mh4_2','mh3_0','mh4_4','mh2_2','mh3_5','mh2_4','mh4_3','mh3_3'];
  const el=h(`<div class="screen mscreen"><div class="mstage">
     <div class="mlights"></div>
     <img class="mban" src="${src('marioban')}">
     <div class="mwalk">${walkers.map((k,i)=>`<img src="${src(k)}" style="--d:${10+i%4*2.5}s;--dl:${-i*2.1}s;--y:${i%3*14}px">`).join('')}</div>
     <div class="mworlds" id="mworlds"></div>
     <div class="mbar">${btn('◀ กลับ','gray sm','back')}
       <span class="mcur">${icH('mg15')} ${fmt(S.eventCur.mario||0)} • ${icH('mg13')} ${fmt(S.mat.mrtk||0)}</span>
       ${btn(`${icH('mg1','bi')} กาชาปองมาริโอ้`,'pink sm','gacha')}${btn(`${icH('mg15','bi')} ร้านเหรียญ`,'yellow sm','shop')}${btn(`${icH('md6','bi')} ของแต่งห้อง`,'green sm','room')}</div>
   </div>${arg.skip||marioSeenIntro?'':`<div class="mcurtain l"></div><div class="mcurtain r"></div><div class="mvalance"></div>`}</div>`);
  ui.appendChild(el); bindCommon&&bindCommon(el);
  const A=a=>$(`[data-act=${a}]`,el);
  A('back').onclick=()=>{ AudioSys.setStyle&&AudioSys.setStyle(null); go('menu'); };
  A('gacha').onclick=()=>{ gIdx=BANNERS.findIndex(b=>b.mario); go('gacha'); };
  A('shop').onclick=()=>{ shopTab='event'; go('shop'); };
  A('room').onclick=()=>{ roomTab='shop'; roomSet='มาริโอ้'; go('room'); };
  if(!marioSeenIntro&&!arg.skip){ marioSeenIntro=true; AudioSys.sfx('levelup'); setTimeout(()=>{ el.classList.add('open'); AudioSys.jingle('star'); },500); setTimeout(()=>drawWorlds(),1500); }
  else drawWorlds();
  function drawWorlds(){ const box=$('#mworlds',el);
    if(arg.w){ openWorld(arg.w); arg.w=null; return; }
    box.innerHTML=`<div class="mwgrid">${[1,2,3,4,5,6,7,8].map(w=>panel(w)).join('')}</div>${panel(9)}`;
    $$('[data-w]',box).forEach((b,i)=>{ b.style.animationDelay=(i*0.12)+'s'; b.onclick=()=>{ if(b.classList.contains('lock')){ toast('ผ่าน World ก่อนหน้าก่อนนะ'); AudioSys.sfx('error'); return; } AudioSys.sfx('click'); openWorld(+b.dataset.w); }; }); }
  function panel(w){ const un=w===1||!!S.estages[`mario-${w-1}-${marioStages(w-1)}`]; const n=marioStages(w), st=marioStars(w);
    return `<div class="mwp ${w===9?'final':''} ${un?'':'lock'}" data-w="${w}"><img src="${src('mwm'+w)}"><div class="mwi"><b>${w===9?'FINAL':'W'+w}</b> ${'★'.repeat(Math.min(3,Math.floor(st/n)))} <small>${st}/${n*3}</small></div>${un?'':'<div class="mlock">🔒</div>'}</div>`; }
  function openWorld(w){ const box=$('#mworlds',el); const D=MARIO_WORLD[w]; const [PW,PH]=D.size; AudioSys.sfx('tab');
    box.innerHTML=`<div class="mworld ${w===9?'final':''}"><div class="mwimg"><img src="${src('mwm'+w)}">
      ${D.dots.map((d,i)=>{ const s=i+1, u=marioUnlocked(w,s), r=S.estages[`mario-${w}-${s}`], b=marioBoss(w,s); return `<button class="mdot ${u?'':'lock'} ${u==='chest'?'wait':''} ${r?'done':''} ${b?'boss':''}" data-s="${s}" style="left:${d[0]/PW*100}%;top:${d[1]/PH*100}%"><b>${s}</b>${r?`<i>${'★'.repeat(r.stars)}</i>`:''}${b?'<em>BOSS</em>':''}</button>`; }).join('')}
      <button class="mq ${S.mario.chest[w]?'got':''} ${S.estages[`mario-${w}-${D.qAfter}`]?'ready':''}" style="left:${qx(w)}%;top:${qy(w)}%">${icH(S.mario.chest[w]?'md108':'md24')}</button>
      </div><div class="row c">${btn('◀ เลือก World','gray sm','wb')}<span class="mwname">World ${w} • ${MW[w].n} • ${MW[w].th}</span></div></div>`;
    $('[data-act=wb]',box).onclick=()=>{ AudioSys.sfx('tab'); drawWorlds(); };
    $('.mq',box).onclick=()=>{ if(S.mario.chest[w]){ toast('เปิดหีบของ World นี้ไปแล้ว'); return; } if(!S.estages[`mario-${w}-${D.qAfter}`]){ toast(`ผ่านด่าน ${D.qAfter} ก่อนถึงจะเข้าห้องหีบสมบัติได้`); return; } marioTreasure(w,()=>openWorld(w)); };
    $$('[data-s]',box).forEach(b=>b.onclick=()=>{ const s=+b.dataset.s, u=marioUnlocked(w,s);
      if(u==='chest'){ toast('เปิดหีบสมบัติ ? ก่อนเดินต่อนะ!'); $('.mq',box).classList.add('shake'); setTimeout(()=>$('.mq',box).classList.remove('shake'),600); return; }
      if(!u){ toast('ผ่านด่านก่อนหน้าก่อน'); AudioSys.sfx('error'); return; }
      AudioSys.sfx('click'); popStageDetail({event:'mario',mw:w,stage:s}); }); }
  function qx(w){ const Q={1:367,2:436,3:427,4:406,5:348,6:538,7:405,8:544,9:1275}; return Q[w]/MARIO_WORLD[w].size[0]*100; }
  function qy(w){ return w===9?52:46; }
}
// ---------- treasure room (3 chests) ----------
const MARIO_DECO_PRIZE=['mg36','mg40','mg63','mg64','mg69','mg72','mg75','md5','md6','md46','md57','md108'];
function marioChestRoll(w){ const r=Math.random(), k=[];
  const pool=[()=>({mrtk:1+Math.floor(w/3)}),()=>({gems:120+w*30}),()=>({gold:8000+w*3000}),()=>({cur_mario:120+w*25}),()=>({evo:3+w}),()=>({umedal:8+w*2}),()=>({book:2+Math.floor(w/2)}),()=>({exp_l:2+w})];
  const big=r<0.18; const o=Object.assign({},pick(pool)(),pick(pool)()); if(big){ o.mrtk=(o.mrtk||0)+2; o.gems=(o.gems||0)+200; }
  if(Math.random()<0.45){ o.deco=pick(MARIO_DECO_PRIZE); } return {o,big}; }
function marioTreasure(w,done){
  const rolls=[0,1,2].map(()=>marioChestRoll(w));
  const m=openModal(`<div class="mtreas"><img class="mtbg" src="${src('mtreasure')}"><div class="mttitle">✨ ห้องหีบสมบัติ World ${w} ✨<small>เลือกหีบ 1 ใบ!</small></div>
    ${[0,1,2].map(i=>`<button class="mchest c${i}" data-c="${i}"><span class="mspark"></span></button>`).join('')}<div class="mtres" id="mtres"></div></div>`,'nobg2 wide');
  AudioSys.jingle('star');
  $$('[data-c]',m).forEach(b=>b.onclick=()=>{ if(m.dataset.done) return; m.dataset.done=1; const i=+b.dataset.c, R=rolls[i];
    b.classList.add('open'); AudioSys.sfx('gacha'); setTimeout(()=>AudioSys.jingle(R.big?'gacha5':'levelup'),400);
    const o=Object.assign({},R.o); const deco=o.deco; delete o.deco; const g=grant(o);
    if(deco){ roomInit(); S.room.owned[deco]=(S.room.owned[deco]||0)+1; }
    S.mario.chest[w]=true; save(true);
    for(let k=0;k<40;k++){ const s=document.createElement('i'); s.className='mconf'; s.style.cssText=`left:${b.offsetLeft+b.offsetWidth/2}px;top:${b.offsetTop+b.offsetHeight/3}px;--x:${(Math.random()-0.5)*600}px;--y:${-200-Math.random()*300}px;--r:${Math.random()*720}deg;background:${pick(['#ffe36b','#ff5f7a','#5fd068','#4fb4ff','#fff'])}`; m.querySelector('.mtreas').appendChild(s); setTimeout(()=>s.remove(),1600); }
    setTimeout(()=>{ $$('[data-c]',m).forEach(o2=>{ if(o2!==b) o2.classList.add('open','dim'); });
      $('#mtres',m).innerHTML=`<div class="mtgot ${R.big?'big':''}">${R.big?'🎉 หีบสมบัติใหญ่! 🎉':'ได้รับ!'}<div class="rws big">${g.map(([k,v])=>rewHTML(k,v)).join('')}${deco?`<div class="rw"><img src="${src(RITEM[deco]?RITEM[deco].img:deco)}"><b>x1</b><small>${RITEM[deco]?RITEM[deco].n:'ของแต่งห้อง'}</small></div>`:''}</div>${btn('ไปต่อ ▶','green','ok')}</div>`;
      $('[data-act=ok]',m).onclick=()=>{ closeModal(m); done&&done(); }; },1100); }); }
